const resp = $input.first().json;
const results = Array.isArray(resp.results) ? resp.results.slice(0, 10) : [];
let news = '';
results.forEach((r, i) => {
  const title = (r.title || 'Untitled').replace(/\s+/g, ' ').trim();
  const content = (r.content || '').replace(/\s+/g, ' ').trim().slice(0, 200);
  const url = r.url || '';
  news += `- ${title} :: ${content} (${url})\n`;
});
if (!news) news = '- No local search results were returned; rely on web research and label staleness.\n';

const instruction = `You are a senior precious-metals analyst writing a PRE-MARKET GOLD BRIEF to be read before the trading day opens. Use web research (WebSearch / WebFetch) to verify and enrich with the very latest specifics, alongside the curated news at the end.

Write a COMPLETE, sharp analysis of gold (XAU/USD) across the three major sessions:
- TOKYO / ASIA (overnight, just traded): what moved, China/Japan/PBoC demand, levels.
- LONDON / LBMA (about to open): the dollar, real yields, ETF flows, European drivers.
- NEW YORK / COMEX (US session ahead): Fed/rate expectations, US data on today's calendar, COMEX positioning.

Also include: an Executive Take (one tight paragraph — likely tone at the open and why), Key Levels (support/resistance with numbers where possible), Today's Catalysts (scheduled data/events, central-bank speakers, geopolitics), and a Risk note. Be specific and quantitative where the data allows; clearly label anything uncertain or stale. Cite sources inline as [n] with a short numbered Sources list at the end.

OUTPUT — CRITICAL: return ONLY one complete, self-contained HTML document — a polished, print-ready report with clean professional inline CSS (a titled header with today's date, clear section headings, readable serif/sans typography, a subtle gold accent, and a small footer "Generated locally · Claude analysis"). No commentary, no markdown, no code fences. Start with <!doctype html> and end with </html>.`;

const prompt = `${instruction}\n\nCURATED NEWS (local):\n${news}`;
return [{ json: { prompt, allowedTools: 'WebSearch WebFetch' } }];

let raw = '';
const j = $input.first().json;
if (j && typeof j.result === 'string') raw = j.result;
else if (j && j.result != null) raw = String(j.result);
else if (typeof j === 'string') raw = j;

let html = String(raw || '').trim();
html = html.replace(/^```html\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();

if (!html) {
  html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Gold Pre-Market Brief</title>' +
    '<style>@page{margin:28mm 20mm;}body{font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#1a1a1a;line-height:1.55;font-size:12pt;}h1{color:#9a7b1f;}.note{border-left:4px solid #c9a227;padding:10px 16px;background:#fdf8e8;}</style>' +
    '</head><body><h1>Gold Pre-Market Brief</h1><div class="note"><p><strong>Claude bridge not reachable — enable it (see docs/BUILD-REPORT.md §6).</strong></p>' +
    '<p>The local SearXNG news was gathered, but the Claude host bridge returned no analysis. Start the bridge and re-run.</p></div></body></html>';
}

return [{ json: { html } }];
